<?php
require_once 'auth.php';require_role(['super_admin','registrar']);require_once 'db.php';
$type=trim($_GET['type']??'');$action=trim($_GET['action']??'');$admin=trim($_GET['admin']??'');$from=trim($_GET['from']??'');$to=trim($_GET['to']??'');$page=safe_page_int($_GET['page']??1);$per=50;$where=[];$params=[];$types='';
if($type!==''){$where[]='entity_type=?';$params[]=$type;$types.='s';}if($action!==''){$where[]='action=?';$params[]=$action;$types.='s';}if($admin!==''){$where[]='admin_username=?';$params[]=$admin;$types.='s';}if($from!==''){$where[]='created_at>=?';$params[]=$from.' 00:00:00';$types.='s';}if($to!==''){$where[]='created_at<=?';$params[]=$to.' 23:59:59';$types.='s';}$w=$where?' WHERE '.implode(' AND ',$where):'';$count=mysqli_prepare($conn,'SELECT COUNT(*) c FROM audit_logs'.$w);if($params)mysqli_stmt_bind_param($count,$types,...$params);mysqli_stmt_execute($count);$total=(int)(mysqli_fetch_assoc(mysqli_stmt_get_result($count))['c']??0);$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$offset=($page-1)*$per;$sql='SELECT * FROM audit_logs'.$w.' ORDER BY id DESC LIMIT '.$per.' OFFSET '.$offset;$st=mysqli_prepare($conn,$sql);if($params)mysqli_stmt_bind_param($st,$types,...$params);mysqli_stmt_execute($st);$r=mysqli_stmt_get_result($st);$logs=[];while($x=mysqli_fetch_assoc($r))$logs[]=$x;$admins=[];$ar=mysqli_query($conn,'SELECT DISTINCT admin_username FROM audit_logs ORDER BY admin_username');while($x=mysqli_fetch_row($ar))$admins[]=$x[0];
?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Audit Log</title><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="modern-ui.css?v=20261006-modern2"></head><body><div class="main-wrapper"><?php include 'admin_nav.php';?><main class="content"><section class="page-heading"><div><span class="page-kicker">Security & Traceability</span><h1>Audit Log</h1><p>Filter administrative activity by date, administrator, entity and action.</p></div></section><section class="feature-card"><form method="get" class="filter-form"><div class="form-grid-3"><div><label>Type</label><input name="type" value="<?=e($type)?>" placeholder="student/result/subject"></div><div><label>Action</label><input name="action" value="<?=e($action)?>" placeholder="UPDATE/CREATE"></div><div><label>Admin</label><select name="admin"><option value="">All</option><?php foreach($admins as $a):?><option value="<?=e($a)?>" <?=$admin===$a?'selected':''?>><?=e($a)?></option><?php endforeach;?></select></div></div><div class="form-grid-2"><div><label>From</label><input type="date" name="from" value="<?=e($from)?>"></div><div><label>To</label><input type="date" name="to" value="<?=e($to)?>"></div></div><div class="button-row"><a class="btn-link btn-secondary" href="audit_log.php">Clear</a><input type="submit" value="Filter"></div></form></section><section class="feature-card wide-card"><div class="table-wrapper"><table class="results-table"><tr><th>Date / Time</th><th>Admin</th><th>Action</th><th>Type</th><th>ID</th><th>Details</th><th>IP</th></tr><?php foreach($logs as $l):?><tr><td><?=e($l['created_at'])?></td><td><?=e($l['admin_username'])?></td><td><strong><?=e($l['action'])?></strong></td><td><?=e($l['entity_type'])?></td><td><?=e($l['entity_id'])?></td><td><?=e($l['details'])?></td><td><?=e($l['ip_address'])?></td></tr><?php endforeach;?></table></div><div class="pagination"><?php for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++):?><a class="filter-chip" href="?<?=http_build_query(array_merge($_GET,['page'=>$i]))?>"><?=$i?></a><?php endfor;?></div></section></main><?php include 'footer.php';?></div></body></html>